  ui_story_40120001_142_option_content = "Entonces... ¿Fue Charon?",
  ui_story_40120001_143_dialog_content = "Ya veo... Viendo que Vice era culp., no veo nin. razón para sos. de nadie más ... incluyéndome a mí.",
  ui_story_40120001_144_dialog_content = "Pero te empezó a gustar esa cosa, y eso fue hace aprox. un mes, también ...",
  ui_story_40120001_148_dialog_content = "Cuando entré a la oficina, no vi nin. etiqueta. Todo lo que vi fueron platos vacíos, la tapa de vidrio y el capuchino, así que pensé que lo bebería...",
  ui_story_40120001_150_dialog_content = "Entonces eso te deja a ti, Philyshy...",
  ui_story_40120001_156_dialog_content = "¿Cuándo llegaron todos a la escena del crimen?",
  ui_story_40120001_157_dialog_content = "No tengo la menor idea... ¿Podemos terminar con esto ya? Mi cerebro ya está frito...",
  ui_story_40120001_158_dialog_content = "Ese día no llevaba reloj, así que no lo recuerdo.",
  ui_story_40120001_159_dialog_content = "N-No estaba prestando atención a la hora. Salí justo después de terminar los pasteles...",
  ui_story_40120001_160_dialog_content = "Sin una cronología prec. de los eventos, no pod. avanzar mucho más en el caso ...",
  ui_story_40120001_161_dialog_content = "Increíble... ¡Los tres estaban involucrados! ¡Todos son culpables!",
