  ui_story_40120001_163_dialog_content = "Ella es una turba enojada de uno... Tengan la certeza de que haré un juicio justo de este caso.",
  ui_story_40120001_164_dialog_content = "Parece que todos <color=#FFB400>est. diciendo la verdad</color>.",
  ui_story_40120001_165_dialog_content = "Por favor explica.",
  ui_story_40120001_166_dialog_content = "Tal vez... ¡Cada uno de sus testimonios es la verdad!",
  ui_story_40120001_167_dialog_content = "¿Todos son la verdad?",
  ui_story_40120001_168_dialog_content = "Sí... Pero primero necesito confirmar algo con Philyshy.",
  ui_story_40120001_169_dialog_content = "Purr... Purr...",
  ui_story_40120001_170_dialog_content = "Parece que uno de los sos. se ha quedado dormido.",
  ui_story_40120001_171_dialog_content = "No, \"ella\" debería despertarse en breve.",
  ui_story_40120001_172_dialog_content = "¿Hm? Tanta gente... ¿Qué día es hoy? ¿Me he perdido algo?",
  ui_story_40120001_173_dialog_content = "(Yumi está aquí... ¡Esta podría ser nuestra opor. de <color=#FFB400>descifrar el caso</color>!)",
  ui_story_40120001_174_dialog_content = "Hola, Yumi. ¿Todavía rec. ese Set de Delicias de la Tarde de hace no mucho?",
  ui_story_40120001_175_dialog_content = "¿Te refieres a esos boca. que estaban en el esc. de Vivian en su oficina? ¡Claro que sí!",
  ui_story_40120001_176_dialog_content = "¡Yumi! ¡¿Fuiste tú todo el tiempo?!",
  ui_story_40120001_177_dialog_content = "¿De qué estás hablando? Cuando Philyshy entró a la oficina, ni siq. se dio cuenta de esa bandeja de bocadillos.",
  ui_story_40120001_178_dialog_content = "Ella tampoco había tomado su siesta de la tarde, así que se quedó dormida poco después.",
  ui_story_40120001_179_dialog_content = "Y luego, como siempre... ¡Era mi turno de salir!",
  ui_story_40120001_180_dialog_content = "¡¡Pero lo que no esp. era ver ese pudín desag. justo en frente de mí cuando me desperté!!",
  ui_story_40120001_181_dialog_content = "Solo hay una persona en el mundo que consid. al queso como su enemigo... ¡Y eres tú, Yumi!",
  ui_story_40120001_182_dialog_content = "De todos modos, hice lo único razonable en esa situación: ¡arranqué la cubierta de vidrio y tiré el pudín por la ventana!",
  ui_story_40120001_183_dialog_content = "¿Y entonces?",
  ui_story_40120001_184_dialog_content = "Y entonces... Rompí la etiqueta y me lavé las manos...",
  ui_story_40120001_185_dialog_content = "¿Qué etiqueta?",
  ui_story_40120001_186_dialog_content = "*Bostezos*... Dime, qué hora es...",
  ui_story_40120001_187_dialog_content = "¡Jefe de Int. Yumi, no se atreva a qued. dormida! ¡No hemos term. aquí!",
  ui_story_40120001_188_dialog_content = "La etiqueta... La tiré ... a la basura...",
  ui_story_40120001_189_dialog_content = "Luego agarré... el vaso co...",
  ui_story_40120001_190_dialog_content = "Capuchino... Purr...",
  ui_story_40120001_191_dialog_content = "¿Podemos... incluso usar una dec. tan ambigua como testimonio?",
  ui_story_40120001_192_dialog_content = "Ya no importa, déjala dormir. Creo... Finalmente llegué al fondo de esto.",
  ui_story_40120001_193_dialog_content = "¿En serio?",
  ui_story_40120001_194_dialog_content = "¡Ent. cuéntanos! ¿Qué pasó exactamente ese día?",
  ui_story_40120001_195_dialog_content = "*Toma un respiro profundo*",
  ui_story_40120001_196_option_content = "Creo que primero fue Philyshy.",
  ui_story_40120001_197_dialog_content = "El segundo fue...",
  ui_story_40120001_198_option_content = "¿Charon?",
  ui_story_40120001_200_dialog_content = "Correcto, lo que sig. que Charon era el tercero en la oficina... Lo tengo ahora.",
  ui_story_40120001_202_option_content = "¿Vice?",
  ui_story_40120001_203_dialog_content = "Eso tendría sentido. ¿Qué pasó después?",
  ui_story_40120001_204_dialog_content = "Volvamos a Philyshy, entonces.",
  ui_story_40120001_205_option_content = "¿Sup. que fue Vice?",
  ui_story_40120001_206_dialog_content = "¡Eso no puede ser correcto! Ent., ¿cómo explicarías la etiqueta? Cuando llegué a la oficina, ¡ya estaba rasgado!",
  ui_story_40120001_207_dialog_content = "Tu no estas equivocado... Vice debería haber sido la segunda persona en la oficina.",
  ui_story_40120001_208_option_content = "Ent., ¿eso sig. que la primera per. fue Charon?",
  ui_story_40120001_210_dialog_content = "Ah, mal de nuevo... Real. necesito tom. esto en serio...",
  ui_story_40120001_211_dialog_content = "Ent. eso solo deja a una persona. El primero en la oficina fue Philyshy.",
  ui_story_40120001_212_option_content = "La primera persona que llegó fue Philyshy.",
  ui_story_40120001_213_option_content = "¿Charon fue el primero, creo?",
  ui_story_40120001_214_dialog_content = "¡Pero eso no explicaría lo que pasó con los pasteles y el pudín! Cuando llegué, lo único que quedaba era el capuchino.",
  ui_story_40120001_215_dialog_content = "Ni cerca... ¡Intenta otra vez!",
  ui_story_40120001_216_option_content = "¡Entonces debería ser Vice!",
  ui_story_40120001_217_dialog_content = "Pero PlayerName... Cuando llegué a la oficina, la etiqueta ya estaba rasgada...",
  ui_story_40120001_218_dialog_content = "Philyshy. Quise decir Philyshy.",
  ui_story_40120001_219_option_content = "Creo que la primera persona en la oficina fue Philyshy",
  ui_story_40120001_220_dialog_content = "Pero como no había dormido la siesta de la tarde, Philyshy estuvo durmiendo todo el tiempo.",
  ui_story_40120001_221_dialog_content = "Mientras tanto, Yumi, que acababa de despertar, se asustó al ver el pudín de queso y lo tiró ráp. por la ventana.",
  ui_story_40120001_222_dialog_content = "Desp., arrancó la mitad de la etiq. que decía \"Vivian\" y la usó para lim. la mano, luego la tiró a la basura.",
  ui_story_40120001_223_dialog_content = "Eso explica por qué la parte de la etiqueta que decía \"Vi-\" se dejó en la tapa de vidrio.",
  ui_story_40120001_224_dialog_content = "Después de eso, por razones que solo conocen los gatos, colocó la tapa sobre los pasteles, dejando el capuchino intacto.",
  ui_story_40120001_225_dialog_content = "Qu... Queso... Muerte a todo queso...",
  ui_story_40120001_226_dialog_content = "Esto resultó en una presunción falsa por parte del sig. sosp. que ingresó a la oficina—",
  ui_story_40120001_227_dialog_content = "Vice.",
  ui_story_40120001_228_dialog_content = "Cuando vio sus pasteles favoritos en el esc. y la portada con una etiqueta que decía \"Vi-\"...",
  ui_story_40120001_229_dialog_content = "Naturalmente, asumió que era su recom. por seguir su dieta.",
  ui_story_40120001_230_dialog_content = "Entonces, felizmente se los comió y tiró las etiquetas a la basura. ¿No es así, Vice?",
  ui_story_40120001_231_dialog_content = "I-Increíble... Eso es exactamente lo que pasó...",
  ui_story_40120001_232_dialog_content = "Es decir, el últ. en entrar en la esc. del crimen... fue Charon.",
  ui_story_40120001_233_dialog_content = "¿Qué vio cuando llegó allí? Platos vacíos, una tapa de cristal y un capuchino solo a un lado.",
  ui_story_40120001_234_dialog_content = "Prob., pensando que lo dejaron allí para que cualq. lo tomara, lo recogió y se lo bebió él mismo.",
  ui_story_40120001_235_dialog_content = "Luego, alrededor de las 3:00 pm, que no fue mucho después de que se fue... Némesis y Vivian reg. juntas a la escena del crimen.",
  ui_story_40120001_236_dialog_content = "En ese mom., los platos y la taza estaban com. vacíos, las etiquetas estaban en la basura y el pobre pudín estaba salpicado en el suelo fuera de la ventana.",
  ui_story_40120001_237_dialog_content = "Una trágica historia de malentendidos, acusaciones, codicia desenfrenada y pura mala suerte. Eso es lo que fue.",
  ui_story_40120001_238_dialog_content = "...",
  ui_story_40120001_239_dialog_content = "En conclusión, el crimen fue perpetrado en partes iguales por Philyshy, Charon y Vice. Caso cerrado.",
  ui_story_40120001_240_dialog_content = "Los tres eran culp., pero ino. desde el principio...",
  ui_story_40120001_241_dialog_content = "Así veo. Por asom. que sea la verdad, me siento aliviado de todos modos.",
  ui_story_40120001_242_dialog_content = "Si no hub. descubierto la verdad hoy, me habría sentido fatal al pensar que había un ladrón entre nosotros.",
  ui_story_40120001_243_dialog_content = "También me gustaría disc. por mi com. emocional anterior. Mi reacción fue comp. inaceptable...",
  ui_story_40120001_244_dialog_content = "¡Pero todos sabían! ¡Estaba planeando disfrutar esos postres tan pronto como terminara mi trabajo del día!",
  ui_story_40120001_245_dialog_content = "Si hay algo que no puedo soportar, ¡es cuando mis planes se arruinan!",
  ui_story_40120001_246_dialog_content = "Entiendo, Jefe... No somos del todo inocentes aquí, y lo sentimos...",
  ui_story_40120001_247_dialog_content = "Que te quiten algo precioso... Tu ira estaba comp. justificada. ¿Cómo pod. hacer las cosas bien, mi señora?",
  ui_story_40120001_248_dialog_content = "¿Qué tal otro set?",
  ui_story_40120001_249_dialog_content = "Parece que no comiste hasta saciarte ese día, PlayerName.",
  ui_story_40120001_250_dialog_content = "Incluso si adquiriéramos otro, Vivian no se sentiría igual que ese día.",
  ui_story_40120001_251_dialog_content = "La satisfacción de sentarse en su cómoda silla después de un largo día de trabajo y dar ese primer bocado...",
  ui_story_40120001_252_dialog_content = "¡Ah! ¡Hab. de trabajo!",
  ui_story_40120001_253_dialog_content = "Oh no...",
